import java.util.*; public class Q08_LoanManagementSystem{static abstract class Loan{double p,t;Loan(double p,double t){this.p=p;this.t=t;}abstract double interest();}static class Home extends Loan{Home(double p,double t){super(p,t);}double interest(){return p*8*t/100;}}static class Car extends Loan{Car(double p,double t){super(p,t);}double interest(){return p*10*t/100;}}public static void main(String[]x){Scanner s=new Scanner(System.in);while(s.hasNextLine()){String[]p=s.nextLine().split(",");Loan l=p[0].equalsIgnoreCase("Home")?new Home(Double.parseDouble(p[1]),Double.parseDouble(p[2])):new Car(Double.parseDouble(p[1]),Double.parseDouble(p[2]));System.out.println(p[0]+" Loan Interest: "+l.interest());}}}
